// Test-only PGlite-shaped adapter to an official PostgreSQL --single backend.
// No sockets, network, shared cluster, substitute digest, or production data.
import {spawn,execFileSync} from 'node:child_process';
import {appendFileSync,mkdtempSync} from 'node:fs';
import {createHash} from 'node:crypto';
import {fileURLToPath} from 'node:url';
import {dirname,resolve,join} from 'node:path';

const root=resolve(dirname(fileURLToPath(import.meta.url)),'../..');
const binary=join(root,'install/bin/postgres'),initdb=join(root,'install/bin/initdb');
const hash=value=>createHash('sha256').update(value).digest('hex');
import {prepareSql} from './sql-framing.js';

export class PGlite {
 static async create(){
  const data=mkdtempSync(join(root,'test-data-'));
  execFileSync(initdb,['-D',data,'--no-locale','--encoding=UTF8','--username=deadline_test'],{stdio:'pipe'});
  const db=new PGlite(data);
  try{await db.ready;await db.exec('CREATE EXTENSION pgcrypto');return db;}
  catch(error){db.child.stdin.end();await db.closed;throw error;}
 }
 constructor(data){
  this.data=data;this.output='';this.pending=undefined;this.sequence=0;
  // Merge stderr into stdout so an ERROR and the following prompt retain order.
  // Positional parameters keep the verified local paths out of shell source.
  this.child=spawn('/bin/bash',['-c','exec "$1" --single -j -D "$2" -c TimeZone=UTC -c log_min_messages=warning -c log_error_verbosity=verbose postgres 2>&1','native-single-test',binary,data],{stdio:['pipe','pipe','pipe']});
  this.ready=new Promise((resolve,reject)=>{this.pending={resolve,reject,startup:true};});
  this.child.stdout.on('data',chunk=>{
   this.output+=String(chunk);
   if(!this.output.endsWith('backend> ')||!this.pending)return;
   const pending=this.pending,result=this.output;this.pending=undefined;this.output='';
   if(/\b(?:ERROR|FATAL|PANIC):/.test(result))pending.reject(Error(result));else pending.resolve(result);
  });
  this.child.once('error',error=>this.pending?.reject(error));
  this.closed=new Promise(resolve=>this.child.once('close',(code,signal)=>{
   this.pending?.reject(Error(`NATIVE_SINGLE_EXIT:${code}:${signal}:${this.output}`));this.pending=undefined;resolve({code,signal});
  }));
 }
 async command(sql){
  if(this.pending)throw Error('NATIVE_SINGLE_CONCURRENT_QUERY_FORBIDDEN');
  const framed=prepareSql(sql)+';\n\n';
  const sequence=++this.sequence;
  try{
   const result=await new Promise((resolve,reject)=>{this.pending={resolve,reject};this.child.stdin.write(framed);});
   appendFileSync(join(root,'logs/native-queries.jsonl'),JSON.stringify({data:this.data,sequence,sqlSha256:hash(sql),framedSha256:hash(framed),sqlBytes:Buffer.byteLength(sql),status:'OK'})+'\n');return result;
  }catch(error){
   appendFileSync(join(root,'logs/native-queries.jsonl'),JSON.stringify({data:this.data,sequence,sqlSha256:hash(sql),framedSha256:hash(framed),sqlBytes:Buffer.byteLength(sql),status:'ERROR',error:String(error)})+'\n');throw error;
  }
 }
 async exec(sql){await this.command(sql);return [];}
 async query(sql,values=[]){
  const substituted=prepareSql(sql,values);
  if(!/^(?:SELECT|WITH)\b/i.test(substituted)){await this.exec(substituted);return {rows:[]};}
  const query=substituted;
  const output=await this.command(`SELECT encode(convert_to(coalesce(json_agg(q)::text,'[]'),'UTF8'),'hex') AS __test_rows FROM (${query}) q`);
  const encoded=output.match(/__test_rows = "([a-f0-9]+)"/);
  if(!encoded)throw Error('NATIVE_SINGLE_ROWS_MISSING:'+output);
  return {rows:JSON.parse(Buffer.from(encoded[1],'hex').toString('utf8'))};
 }
 async close(){this.child.stdin.end();const result=await this.closed;if(result.code!==0)throw Error('NATIVE_SINGLE_CLOSE_FAILED:'+JSON.stringify(result));}
}
